    rows = ''.join('<tr><td>%s</td><td style="white-space:nowrap"><span class="box"></span>ผ่าน &nbsp; <span class="box"></span>ไม่ผ่าน</td><td></td><td></td></tr>' % DAY[d] for d in PLAN[c])
    return ('<div class="sc"><div class="sh"><b>%s %s</b><span>%s · ผู้ทดสอบ: %s</span></div><div class="sb">'
            '<div class="prob"><b>ปัญหาเดิม:</b> %s</div><div class="g"><div><div class="l">ขั้นตอน</div><ol>%s</ol></div>'
            '<div><div class="l">ผลที่ต้องเห็น</div><ul>%s</ul></div></div>'
            '<div><span class="l">หลักฐาน:</span> %s</div><div><span class="l">เกณฑ์ผ่าน:</span> %s</div>'
            '<table class="res" style="margin-top:4px"><tr><th style="width:22%%">วันที่ทดสอบ (ตามแผน)</th><th style="width:24%%">ผล</th><th>หมายเหตุ / ปัญหาที่พบ</th><th style="width:20%%">ลายเซ็นผู้ทดสอบ</th></tr>'
            '%s</table>'
            '</div></div>') % (c, n, uc, who, prob, ''.join('<li>%s</li>' % x for x in steps), ''.join('<li>%s</li>' % x for x in see), ev, ok, rows)

